    nxt = ORIG.find("\n\n", b_end)
    b = min(nxt if nxt != -1 else len(ORIG), b_end + 160)
    pre, post = ORIG[a:i], ORIG[b_end:b]
    if a > 0 and ORIG[a - 1] not in "\n ":
