\label{tab:mixing}
\begin{tabular*}{\journalfloatwidth}{@{\extracolsep{\fill}}llccccc@{}}
\toprule
Dataset & Rule & Acc. (\%) & JFI & Never sel. (\%) & Max. wait & Weakest 10\% (\%) \\
\midrule
